/// Event-interface family selected by the RSJS event registry.
///
/// This generated enum lets compiler crates consume the same vocabulary as
/// the Rust witness marker module above.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum EventInterface {
    Event,
    MouseEvent,
    InputEvent,
    ChangeEvent,
    ClipboardEvent,
    KeyboardEvent,
    WheelEvent,
    CompositionEvent,
    DragEvent,
    ToggleEvent,
    AnimationEvent,
    TransitionEvent,
    PointerEvent,
    TouchEvent,
    PopStateEvent,
    HashChangeEvent,
    StorageEvent,
    SubmitEvent,
}

impl EventInterface {
    /// Rust marker name in [`event_interface`].
    pub const fn as_rust_marker_name(self) -> &'static str {
        match self {
            Self::Event => "Event",
            Self::MouseEvent => "MouseEvent",
            Self::InputEvent => "InputEvent",
            Self::ChangeEvent => "ChangeEvent",
            Self::ClipboardEvent => "ClipboardEvent",
            Self::KeyboardEvent => "KeyboardEvent",
            Self::WheelEvent => "WheelEvent",
            Self::CompositionEvent => "CompositionEvent",
            Self::DragEvent => "DragEvent",
            Self::ToggleEvent => "ToggleEvent",
            Self::AnimationEvent => "AnimationEvent",
            Self::TransitionEvent => "TransitionEvent",
            Self::PointerEvent => "PointerEvent",
            Self::TouchEvent => "TouchEvent",
            Self::PopStateEvent => "PopStateEvent",
            Self::HashChangeEvent => "HashChangeEvent",
            Self::StorageEvent => "StorageEvent",
            Self::SubmitEvent => "SubmitEvent",
        }
    }
}

/// Bridge implemented by the canonical event handles owned by `rsjs`.
///
/// `rsjs_web` owns interface vocabulary but deliberately does not define a
/// second public event-handle family.
pub trait EventParam {
    /// DOM target represented by this event's compiler-selected current target.
    type CurrentTarget: dom::DomTargetMarker;
}

/// Bridge implemented when an `rsjs` event handle matches an interface family.
pub trait EventFor<Interface>: EventParam
where
    Interface: event_interface::Interface,
{
}

